function MobileNav({ view, setView }: { view: View; setView: (view: View) => void }) { const items: { id: View; label: string; icon: typeof LayoutDashboard }[] = [{ id: 'dashboard', label: 'Home', icon: LayoutDashboard }, { id: 'apply', label: 'Apply', icon: Zap }, { id: 'applications', label: 'Tracker', icon: BriefcaseBusiness }, { id: 'inbox', label: 'Inbox', icon: Inbox }, { id: 'settings', label: 'Profile', icon: UserRound }]; return <nav className="mobile-nav">{items.map(({ id, label, icon: Icon }) => <button key={id} className={view === id ? 'active' : ''} onClick={() => setView(id)}><Icon size={19} /><span>{label}</span></button>)}</nav>; }

export default function App() { const [auth, setAuth] = useState<AuthView>('landing'); const [entered, setEntered] = useState(false); if (entered) return <AppShell onLogout={() => { setEntered(false); setAuth('landing'); }} />; if (auth === 'landing') return <Landing onAuth={setAuth} />; return <Auth mode={auth as 'signin' | 'signup' | 'otp'} onAuth={setAuth} onEnter={() => setEntered(true)} />; }
